package com.learnhub.audit.autoconfigure;

import java.time.Duration;
import org.springframework.boot.autoconfigure.AutoConfiguration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;

@AutoConfiguration
@ConditionalOnProperty(prefix = "learnhub.audit", name = "enabled", havingValue = "true")
@EnableConfigurationProperties(AuditAutoConfiguration.AuditProperties.class)
public class AuditAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean
    AuditClient auditClient(AuditProperties properties) {
        return new AuditClient(properties.endpoint(), properties.timeout());
    }

    @ConfigurationProperties(prefix = "learnhub.audit")
    public record AuditProperties(String endpoint, Duration timeout) {

        public AuditProperties {
            endpoint = endpoint == null ? "http://localhost:9000" : endpoint;
            timeout = timeout == null ? Duration.ofSeconds(2) : timeout;
        }
    }

    public record AuditClient(String endpoint, Duration timeout) {

        public void record(String action) {
            System.out.println("audit " + action + " -> " + endpoint);
        }
    }
}

package com.learn.hub.actuator;

import java.time.Instant;
import org.springframework.boot.actuate.endpoint.annotation.Endpoint;
import org.springframework.boot.actuate.endpoint.annotation.ReadOperation;
import org.springframework.boot.actuate.endpoint.annotation.Selector;
import org.springframework.stereotype.Component;

@Component
@Endpoint(id = "learnhub")
public class LearnHubEndpoint {

    private final ContentStats stats;

    public LearnHubEndpoint(ContentStats stats) {
        this.stats = stats;
    }

    @ReadOperation
    public Report report() {
        return new Report(stats.topicCount(), stats.quizCount(), Instant.now());
    }

    @ReadOperation
    public TopicDetail topic(@Selector String slug) {
        return stats.find(slug)
                .map(topic -> new TopicDetail(topic.slug(), topic.title(), topic.concepts()))
                .orElseThrow(() -> new IllegalArgumentException("unknown topic: " + slug));
    }

    public record Report(int topics, int quizzes, Instant sampledAt) { }

    public record TopicDetail(String slug, String title, int concepts) { }
}
